&lt;div class=&quot;BDtitre&quot;&gt;Armure de d&#233;placement spirituel&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Illusion.html&quot; title=&quot;Illusion&quot;&gt;Illusion&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; puissantes ; &lt;b&gt;NLS&lt;/b&gt; 11 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques-Sp&#233;cifiques.html&quot; title=&quot;Armures magiques sp&#233;cifiques&quot;&gt;armure&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 25 160 po ; &lt;b&gt;Poids&lt;/b&gt; 7,5 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Cette &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Ombre-Sup&#233;rieure.html&quot; title=&quot;ombre sup&#233;rieure (propri&#233;t&#233;)&quot;&gt;ombre sup&#233;rieure&lt;/a&gt; +2&lt;/i&gt; est s&#233;duisante mais inqui&#233;tante. Elle donne &#224; son porteur la capacit&#233; d’utiliser cinq fois par jour &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disparition.html&quot; title=&quot;Disparition&quot;&gt;disparition&lt;/a&gt;&lt;/i&gt; comme un pouvoir magique &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;incantation rapide&lt;/a&gt;. Si un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Mythique.html&quot; title=&quot;mythique&quot;&gt;mythique&lt;/a&gt; utilise ce pouvoir de &lt;i&gt;disparition&lt;/i&gt;, il peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour &#233;galement se rendre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Intangible.html&quot; title=&quot;Intangible&quot;&gt;intangible&lt;/a&gt; pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d’armes et armures magiques&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Artisan-Mythique-(Mythique).html&quot; title=&quot;Artisan mythique (mythique)&quot;&gt;Artisan mythique&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disparition.html&quot; title=&quot;Disparition&quot;&gt;disparition&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-&#201;th&#233;r&#233;e.html&quot; title=&quot;Forme &#233;th&#233;r&#233;e&quot;&gt;forme &#233;th&#233;r&#233;e&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 12 660 po
&lt;/div&gt;
